SPRITE_SVG = lzma.decompress(base64.b64decode(_SPRITE_B64)).decode('utf-8')


def emoji_svg(code):
    m = re.search('<symbol id="e' + re.escape(code) + '"[^>]*>(.*?)</symbol>', SPRITE_SVG, re.S)
    if not m:
        return ''
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36">' + m.group(1) + '</svg>'


def has_emoji(code):
    return ('id="e' + re.escape(code) + '"') in SPRITE_SVG
